import Foundation

// Empirical nominal portrait rendering preset from the user-provided Fusion
// reference. This is rendering tuning, not measured properties of another
// source scene. U/W demonstrated actual blur and lighting on device.
// Versioned separately from global Photos/PhotoKit compatibility validation.
enum PhotoDepthRenderingProfile {
  private static let base64 = ""

  static func make() throws -> Data {
    guard let data = Data(base64Encoded: base64), data.prefix(4) == Data("REND".utf8),
          data.count >= 16, (data.count - 16) % 8 == 0 else { throw PhotoDepthError.invalidImage }
    return data
  }
}
